/* VCD dumping routines */

unsigned int MOD_mkTb_r2_n128::dump_VCD_defs(unsigned int levels)
{
  vcd_write_scope_start(sim_hdl, inst_name);
  vcd_num = vcd_reserve_ids(sim_hdl, 21u);
  unsigned int num = vcd_num;
  for (unsigned int clk = 0u; clk < bk_num_clocks(sim_hdl); ++clk)
    vcd_add_clock_def(sim_hdl, this, bk_clock_name(sim_hdl, clk), bk_clock_vcd_num(sim_hdl, clk));
  vcd_write_def(sim_hdl, bk_clock_vcd_num(sim_hdl, __clk_handle_0), "CLK", 1u);
  vcd_write_def(sim_hdl, num++, "RST_N", 1u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "signed_0___d72", 32u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "signed_128___d6", 32u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "signed_1___d73", 32u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "signed_2___d5", 32u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "signed_384___d7", 32u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "signed_388___d8", 32u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "v__h10929", 64u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "v__h8921", 64u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "x__h10849", 11u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "x__h19692", 32u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "x__h19767", 11u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "x__h19807", 32u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "x__h19814", 32u);
  num = INST_t_checked.dump_VCD_defs(num);
  num = INST_t_cyc.dump_VCD_defs(num);
  num = INST_t_errors.dump_VCD_defs(num);
  num = INST_t_first_out.dump_VCD_defs(num);
  num = INST_t_recv_idx.dump_VCD_defs(num);
  num = INST_t_send_idx.dump_VCD_defs(num);
  num = INST_t_started.dump_VCD_defs(num);
  if (levels != 1u)
  {
    unsigned int l = levels == 0u ? 0u : levels - 1u;
    num = INST_d.dump_VCD_defs(l);
  }
  vcd_write_scope_end(sim_hdl);
  return num;
}

void MOD_mkTb_r2_n128::dump_VCD(tVCDDumpType dt, unsigned int levels, MOD_mkTb_r2_n128 &backing)
{
  vcd_defs(dt, backing);
  vcd_prims(dt, backing);
  if (levels != 1u)
    vcd_submodules(dt, levels - 1u, backing);
}

void MOD_mkTb_r2_n128::vcd_defs(tVCDDumpType dt, MOD_mkTb_r2_n128 &backing)
{
  unsigned int num = vcd_num;
  if (dt == VCD_DUMP_XS)
  {
    vcd_write_x(sim_hdl, num++, 1u);
    vcd_write_x(sim_hdl, num++, 32u);
    vcd_write_x(sim_hdl, num++, 32u);
    vcd_write_x(sim_hdl, num++, 32u);
    vcd_write_x(sim_hdl, num++, 32u);
    vcd_write_x(sim_hdl, num++, 32u);
    vcd_write_x(sim_hdl, num++, 32u);
    vcd_write_x(sim_hdl, num++, 64u);
    vcd_write_x(sim_hdl, num++, 64u);
    vcd_write_x(sim_hdl, num++, 11u);
    vcd_write_x(sim_hdl, num++, 32u);
    vcd_write_x(sim_hdl, num++, 11u);
    vcd_write_x(sim_hdl, num++, 32u);
    vcd_write_x(sim_hdl, num++, 32u);
  }
  else
    if (dt == VCD_DUMP_CHANGES)
    {
      if ((backing.PORT_RST_N) != PORT_RST_N)
      {
	vcd_write_val(sim_hdl, num, PORT_RST_N, 1u);
	backing.PORT_RST_N = PORT_RST_N;
      }
      ++num;
      if ((backing.DEF_signed_0___d72) != DEF_signed_0___d72)
      {
	vcd_write_val(sim_hdl, num, DEF_signed_0___d72, 32u);
	backing.DEF_signed_0___d72 = DEF_signed_0___d72;
      }
      ++num;
      if ((backing.DEF_signed_128___d6) != DEF_signed_128___d6)
      {
	vcd_write_val(sim_hdl, num, DEF_signed_128___d6, 32u);
	backing.DEF_signed_128___d6 = DEF_signed_128___d6;
      }
      ++num;
      if ((backing.DEF_signed_1___d73) != DEF_signed_1___d73)
      {
	vcd_write_val(sim_hdl, num, DEF_signed_1___d73, 32u);
	backing.DEF_signed_1___d73 = DEF_signed_1___d73;
      }
      ++num;
      if ((backing.DEF_signed_2___d5) != DEF_signed_2___d5)
      {
	vcd_write_val(sim_hdl, num, DEF_signed_2___d5, 32u);
	backing.DEF_signed_2___d5 = DEF_signed_2___d5;
      }
      ++num;
      if ((backing.DEF_signed_384___d7) != DEF_signed_384___d7)
      {
	vcd_write_val(sim_hdl, num, DEF_signed_384___d7, 32u);
	backing.DEF_signed_384___d7 = DEF_signed_384___d7;
      }
      ++num;
      if ((backing.DEF_signed_388___d8) != DEF_signed_388___d8)
      {
	vcd_write_val(sim_hdl, num, DEF_signed_388___d8, 32u);
	backing.DEF_signed_388___d8 = DEF_signed_388___d8;
      }
      ++num;
      if ((backing.DEF_v__h10929) != DEF_v__h10929)
      {
	vcd_write_val(sim_hdl, num, DEF_v__h10929, 64u);
	backing.DEF_v__h10929 = DEF_v__h10929;
      }
      ++num;
      if ((backing.DEF_v__h8921) != DEF_v__h8921)
      {
	vcd_write_val(sim_hdl, num, DEF_v__h8921, 64u);
	backing.DEF_v__h8921 = DEF_v__h8921;
      }
      ++num;
      if ((backing.DEF_x__h10849) != DEF_x__h10849)
      {
	vcd_write_val(sim_hdl, num, DEF_x__h10849, 11u);
	backing.DEF_x__h10849 = DEF_x__h10849;
      }
      ++num;
      if ((backing.DEF_x__h19692) != DEF_x__h19692)
      {
	vcd_write_val(sim_hdl, num, DEF_x__h19692, 32u);
	backing.DEF_x__h19692 = DEF_x__h19692;
      }
      ++num;
      if ((backing.DEF_x__h19767) != DEF_x__h19767)
      {
	vcd_write_val(sim_hdl, num, DEF_x__h19767, 11u);
	backing.DEF_x__h19767 = DEF_x__h19767;
      }
      ++num;
      if ((backing.DEF_x__h19807) != DEF_x__h19807)
      {
	vcd_write_val(sim_hdl, num, DEF_x__h19807, 32u);
	backing.DEF_x__h19807 = DEF_x__h19807;
      }
      ++num;
      if ((backing.DEF_x__h19814) != DEF_x__h19814)
      {
	vcd_write_val(sim_hdl, num, DEF_x__h19814, 32u);
	backing.DEF_x__h19814 = DEF_x__h19814;
      }
      ++num;
    }
    else
    {
      vcd_write_val(sim_hdl, num++, PORT_RST_N, 1u);
      backing.PORT_RST_N = PORT_RST_N;
      vcd_write_val(sim_hdl, num++, DEF_signed_0___d72, 32u);
      backing.DEF_signed_0___d72 = DEF_signed_0___d72;
      vcd_write_val(sim_hdl, num++, DEF_signed_128___d6, 32u);
      backing.DEF_signed_128___d6 = DEF_signed_128___d6;
      vcd_write_val(sim_hdl, num++, DEF_signed_1___d73, 32u);
      backing.DEF_signed_1___d73 = DEF_signed_1___d73;
      vcd_write_val(sim_hdl, num++, DEF_signed_2___d5, 32u);
      backing.DEF_signed_2___d5 = DEF_signed_2___d5;
      vcd_write_val(sim_hdl, num++, DEF_signed_384___d7, 32u);
      backing.DEF_signed_384___d7 = DEF_signed_384___d7;
      vcd_write_val(sim_hdl, num++, DEF_signed_388___d8, 32u);
      backing.DEF_signed_388___d8 = DEF_signed_388___d8;
      vcd_write_val(sim_hdl, num++, DEF_v__h10929, 64u);
      backing.DEF_v__h10929 = DEF_v__h10929;
      vcd_write_val(sim_hdl, num++, DEF_v__h8921, 64u);
      backing.DEF_v__h8921 = DEF_v__h8921;
      vcd_write_val(sim_hdl, num++, DEF_x__h10849, 11u);
      backing.DEF_x__h10849 = DEF_x__h10849;
      vcd_write_val(sim_hdl, num++, DEF_x__h19692, 32u);
      backing.DEF_x__h19692 = DEF_x__h19692;
      vcd_write_val(sim_hdl, num++, DEF_x__h19767, 11u);
      backing.DEF_x__h19767 = DEF_x__h19767;
      vcd_write_val(sim_hdl, num++, DEF_x__h19807, 32u);
      backing.DEF_x__h19807 = DEF_x__h19807;
      vcd_write_val(sim_hdl, num++, DEF_x__h19814, 32u);
      backing.DEF_x__h19814 = DEF_x__h19814;
    }
}

void MOD_mkTb_r2_n128::vcd_prims(tVCDDumpType dt, MOD_mkTb_r2_n128 &backing)
{
  INST_t_checked.dump_VCD(dt, backing.INST_t_checked);
  INST_t_cyc.dump_VCD(dt, backing.INST_t_cyc);
  INST_t_errors.dump_VCD(dt, backing.INST_t_errors);
  INST_t_first_out.dump_VCD(dt, backing.INST_t_first_out);
  INST_t_recv_idx.dump_VCD(dt, backing.INST_t_recv_idx);
  INST_t_send_idx.dump_VCD(dt, backing.INST_t_send_idx);
  INST_t_started.dump_VCD(dt, backing.INST_t_started);
}

void MOD_mkTb_r2_n128::vcd_submodules(tVCDDumpType dt,
				      unsigned int levels,
				      MOD_mkTb_r2_n128 &backing)
{
  INST_d.dump_VCD(dt, levels, backing.INST_d);
}
